# -*- coding: utf-8 -*-
S = "полный обзор задач 11 класса (очередь G9–G11), проверено вычислением (разбор по случаям параметра, оценка $|\\sin|,|\\cos|\\le1$); условия сверены с текстом учебника"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G11_TB_15_4*_15_25_b", r"при $a=-1$ первое уравнение $0\cdot y=0$, но второе $x+y=-1$ связывает переменные: $x=-1-y$, $y\in\mathbb R$; ключ «$x,y\in\mathbb R$» неверен",
  k=r"$a=-1$: $x=-1-y$, $y \in \mathbb{R}$; $a \neq -1$: $x=1$, $y=a-1$",
  dnew={0: (r"$a=-1$: $x \in \mathbb{R}$, $y \in \mathbb{R}$; $a \neq -1$: $x=1$, $y=a-1$", r"Ученик увидел, что при $a=-1$ первое уравнение обращается в $0\cdot y=0$, и объявил $x$ и $y$ произвольными; но второе уравнение $x+y=-1$ связывает их: $x=-1-y$."),
        1: (r"$a=-1$: $x=-1-y$, $y \in \mathbb{R}$; $a \neq -1$: $x=a-1$, $y=1$", r"Ученик поменял местами значения: из $(a+1)y=a^{2}-1$ получается $y=a-1$, а $x=a-y=1$."),
        2: (r"$a=-1$: $x=-1-y$, $y \in \mathbb{R}$; $a \neq -1$: $x=1$, $y=a+1$", r"Ученик сократил $\frac{a^{2}-1}{a+1}$ и получил $a+1$ вместо $a-1$.")})
E("G11_TB_15_4*_15_29_a", r"$3\sin\frac x2+\cos y=4$: при $\sin\frac x2=s$, $\cos y=4-3s$ и $|\cos y|\le1$ получаем $s\in[1;\frac53]$, а $|s|\le1$ даёт $s=1$, $\cos y=1$; тогда $(a-3)(a+2)s=a-3$ при $s=1$ верно лишь при $a=3$ или $a=-1$; прежний ключ ($a\in[-\frac75;-1]$, $\sin\frac x2=\frac1{a+2}>1$) нарушал $|\sin|\le1$",
  k=r"При $a=-1$ и при $a=3$: $\sin\left(\dfrac{x}{2}\right)=1$, $\cos y=1$, то есть $x=\pi+4\pi k$, $y=2\pi n$, $k,n \in \mathbb{Z}$; при остальных $a$ решений нет",
  dnew={0: (r"При $a=3$: $x=\pi+4\pi k$, $y=2\pi n$; при остальных $a$ решений нет", r"Ученик нашёл случай $a=3$ (уравнение $(a-3)(a+2)s=a-3$ обращается в $0=0$), но потерял $a=-1$: там $s=\frac{1}{a+2}=1$ и $\cos y=1$ тоже подходят."),
        1: (r"При $a\in\left[-\dfrac{7}{5};-1\right]$: $\sin\dfrac{x}{2}=\dfrac{1}{a+2}$, $\cos y=4-\dfrac{3}{a+2}$; при остальных $a$ решений нет", r"Ученик проверил только $|\cos y|\le1$ и не проверил $|\sin\frac{x}{2}|\le1$: при $a<-1$ имеем $\frac{1}{a+2}>1$."),
        2: (r"При любом $a\neq-2$: $\sin\dfrac{x}{2}=\dfrac{1}{a+2}$, $\cos y=4-\dfrac{3}{a+2}$", r"Ученик выразил $\sin\frac{x}{2}$ и $\cos y$ через $a$, но не проверил, что они лежат в $[-1;1]$.")})
E("G11_TB_15_4*_15_29_b", r"$3\sin\frac y2+\cos x=-4$: $\cos x=-4-3s$, $|\cos x|\le1\Rightarrow s\in[-\frac53;-1]$, вместе с $|s|\le1$: $s=-1$, $\cos x=-1$; тогда $(a+3)(a-2)s=3(a+3)$ при $s=-1$ верно лишь при $a=-3$ и $a=-1$; промежуток $-3<a<-1$ в прежнем ключе давал $\cos x<-1$",
  k=r"При $a=-3$ и при $a=-1$: $x=\pi+2\pi k$, $y=-\pi+4\pi n$, $k,n \in \mathbb{Z}$; при остальных $a$ решений нет",
  dnew={0: (r"При $a=-3$ и $a=-1$: $x=2\pi k$, $y=4\pi n$; при остальных $a$ решений нет", r"Ученик верно выделил $a=-3$ и $a=-1$, но при $\cos x=-1$ записал $x=2\pi k$ вместо $x=\pi+2\pi k$, а при $\sin\frac{y}{2}=-1$ — $y=4\pi n$ вместо $-\pi+4\pi n$."),
        1: (r"При $a=-3$ и $a=-1$: $x=\pi+2\pi k$, $y=-\pi+4\pi n$; при $-3<a<-1$: $\cos x=-4-\dfrac{9}{a-2}$, $\sin\dfrac{y}{2}=\dfrac{3}{a-2}$; при остальных $a$ решений нет", r"Ученик записал решение для $-3<a<-1$, не проверив $|\cos x|\le1$: там $-4-\frac{9}{a-2}<-1$."),
        2: (r"При любом $a\neq2$: $\cos x=-4-\dfrac{9}{a-2}$, $\sin\dfrac{y}{2}=\dfrac{3}{a-2}$", r"Ученик выразил $\cos x$ и $\sin\frac{y}{2}$ через $a$, но не проверил, что они лежат в $[-1;1]$.")})
E("G11_TB_15_4*_15_31_a", r"$x\ge1$: $x=\frac{a+2}{a-1}$, подходит при $a>1$; $x<1$: $x=\frac{a-2}{a+1}$, подходит при $a>-1$; единственное решение при $-1<a\le1$ ($a=1$: $x=-0{,}5$; $a=0$: $x=-2$), при $a>1$ два, при $a\le-1$ нет; прежний ключ содержал только два значения $a$",
  k=r"$a \in (-1; 1]$, $x=\dfrac{a-2}{a+1}$ (в частности, $a=1$: $x=-0{,}5$; $a=0$: $x=-2$)",
  dnew={0: (r"$a = 1$: $x = -0{,}5$; $a = 0$: $x = -2$", r"Ученик нашёл единственное решение лишь при двух значениях $a$, не заметив, что при всех $a\in(-1;1]$ ветвь $x\ge1$ корней не даёт, а ветвь $x<1$ даёт ровно один корень."),
        1: (r"$a \in (-1; 1)$, $x=\dfrac{a-2}{a+1}$", r"Ученик исключил $a=1$: при $a=1$ ветвь $x\ge1$ не имеет корней, а ветвь $x<1$ даёт $x=-0{,}5$ — единственное решение."),
        2: (r"$a \in (-1; +\infty)$, $x=\dfrac{a-2}{a+1}$", r"Ученик рассмотрел только ветвь $x<1$ и не проверил ветвь $x\ge1$: при $a>1$ появляется второй корень $x=\frac{a+2}{a-1}$.")})
